import React, { Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import { Splat, OrbitControls } from "@react-three/drei";

const SplatViewer = ({ url }) => (
  <div style={{ width: "100%", height: "500px", borderRadius: "12px", overflow: "hidden", background: "#111" }}>
    <Canvas camera={{ position: [0, 0, 3], fov: 60 }}>
      <Suspense fallback={null}>
        <Splat src={url} />
      </Suspense>
      <OrbitControls />
    </Canvas>
  </div>
);

const Experiments = () => {
  return (
    <section className="container pt-4 pb-5" id="experiments" style={{ maxWidth: "1200px" }}>
      <h2 className="text-dark montserrat-bold text-uppercase text-center py-1">
        Experiments
      </h2>
      <div className="row align-items-center mt-4">
        <div className="col-12 col-md-4 mb-4 mb-md-0">
          <h5 className="montserrat-sbold">My Table</h5>
          <p className="montserrat-light">
            A 3D Gaussian Splatting reconstruction of my desk, captured with 12
            photos and trained using gsplat. Drag to orbit, scroll to zoom.
          </p>
        </div>
        <div className="col-12 col-md-8">
          <SplatViewer url={process.env.PUBLIC_URL + "/my_table.splat"} />
        </div>
      </div>
    </section>
  );
};

export default Experiments;
